const body = $json.body || $json;
const message = String(body.message || '').trim();
const locale = body.locale === 'en' ? 'en' : 'fa';
const sessionId = String(body.sessionId || 'anonymous');
if (!message) {
  throw new Error('message is required');
}
return [{ json: { message, locale, sessionId } }];

const locale = $('Retrieve Top Chunks').first().json.locale;
const fallback = locale === 'fa'
  ? 'الان نتوانستم پاسخ بسازم. لطفاً دوباره تلاش کنید یا از صفحه تماس پیام بگذارید.'
  : 'I could not generate a reply right now. Please try again or use the contact page.';

const content = $json.choices?.[0]?.message?.content?.trim() || '';
let reply = fallback;

if (content) {
  try {
    const parsed = JSON.parse(content);
    if (parsed && typeof parsed.reply === 'string' && parsed.reply.trim()) {
      reply = parsed.reply.trim();
    } else if (typeof parsed === 'string' && parsed.trim()) {
      reply = parsed.trim();
    }
  } catch {
    reply = content;
  }
}

return [{ json: { reply } }];
